#nullable enable // autogenerated

using System.Linq;
using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Grids;
using MVZ2Logic;
using MVZ2Logic.Entities;
using MVZ2Logic.HeldItems;
using MVZ2Logic.Placements;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Entities;
using PVZEngine.Grids;
using PVZEngine.Placements;

namespace MVZ2.GameContent.Placements
{
    public class UpgradePlaceMethod : PlaceMethod, IEntityTwinklePlaceMethod
    {
        public bool ShouldMakeEntityTwinkle(PlacementDefinition placement, Entity entity, EntityDefinition entityDef)
        {
            return entityDef.IsUpgradeBlueprint() && entity.CanUpgradeToContraption(entityDef) && entity.IsFriendlyEntity();
        }
        public override NamespaceID? GetPlaceError(PlacementDefinition placement, LawnGrid grid, EntityDefinition entity)
        {
            using var gridEntities = grid.GetEntitiesDisposeable();
            var entities = gridEntities.Value;
            if (entities.Count <= 0)
            {
                return VanillaGridStatus.onlyUpgrade;
            }
            var upgradeEntity = entities.FirstOrDefault(e => CanUpgradeOn(entity, e));
            if (!upgradeEntity.ExistsAndAlive())
            {
                return VanillaGridStatus.onlyUpgrade;
            }
            var layersToTake = entity.GetGridLayersToTake();
            var conflictEntities = layersToTake.Select(l => grid.GetLayerEntity(l)).OfType<Entity>();
            if (conflictEntities.Any(e => e != upgradeEntity))
            {
                return VanillaGridStatus.alreadyTaken;
            }
            return null;
        }
        public override PlaceOutput PlaceEntity(PlacementDefinition placement, LawnGrid grid, EntityDefinition entityDef, PlaceParams param)
        {
            using var gridEntities = grid.GetEntitiesDisposeable();
            var entities = gridEntities.Value;
            var entity = entities.FirstOrDefault(e => e.CanUpgradeToContraption(entityDef));
            if (entity != null && entity.Exists())
            {
                bool isCommandBlock = param.IsCommandBlock();
                var ent = entity.UpgradeToContraption(entityDef.GetID());
                if (ent != null)
                {
                    if (isCommandBlock)
                    {
                        ent.AddBuff<ImitatedBuff>();
                    }
                    ent.SetVariant(param.GetVariant());
                }
                return new PlaceOutput(ent, entityDef)
                {
                    isCommandBlock = isCommandBlock,
                    increaseTakenConveyorSeed = true,
                };
            }
            return PlaceOutput.InvalidOutput;
        }
        public static bool CanUpgradeOn(EntityDefinition entity, Entity target)
        {
            return target.CanUpgradeToContraption(entity) && target.IsFriendlyEntity();
        }
    }
}
